/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.css3;import page2020.view.Value;public class C3flex {	public static final class Attr {		public static final String display = "display";		public static final String direction = "flex-direction";		public static final String wrap = "flex-wrap";		public static final String flow = "flex-flow";		public static final String justify = "justify-content";		public static final String items = "align-items";		public static final String content = "align-content";		public static final String self = "align-self";		public static final String order = "order";		public static final String grow = "flex-grow";		public static final String shrink = "flex-shrink";		public static final String basis = "flex-basis";		public static final String flex = "flex";	}	public static final class Flex {		public static final String row = "row";		public static final String rowReverse = "row-reverse";		public static final String column = "column";		public static final String columnReverse = "column-reverse";		public static final String nowrap = "nowrap";		public static final String wrap = "wrap";		public static final String wrapReverse = "wrap-reverse";	}	public static final class Justify {		public static final String start = "justify-content-start";		public static final String end = "justify-content-end";		public static final String center = "justify-content-center";		public static final String between = "justify-content-between";		public static final String around = "justify-content-around";	}	public static final class Align {		public static final String start = "align-content-start";		public static final String end = "align-content-end";		public static final String center = "align-content-center";		public static final String between = "align-content-between";		public static final String around = "align-content-around";		public static final String stretch = "align-content-stretch";	}	public static final class Items {		public static final String start = "align-items-start";		public static final String end = "align-items-end";		public static final String center = "align-items-center";		public static final String stretch = "align-items-stretch";		public static final String baseline = "align-items-baseline";	}	public static final class Self {		public static final String start = "flex-self-start";		public static final String end = "flex-self-end";		public static final String center = "flex-self-center";		public static final String stretch = "flex-self-stretch";		public static final String baseline = "flex-self-baseline";	}	public Value display() {		return new Value().name(Attr.display).text("flex");	}	public Value direction(String direction) {		return new Value().name(Attr.direction).text(direction);	}	public Value wrap(String wrap) {		return new Value().name(Attr.wrap).text(wrap);	}	public Value flow(String direction, String wrap) {		return new Value().name(Attr.flow).text(direction + " " + wrap);	}	public Value justify(String justify) {		return new Value().name(Attr.justify).text(justify);	}	public Value items(String items) {		return new Value().name(Attr.items).text(items);	}	public Value content(String content) {		return new Value().name(Attr.content).text(content);	}	public Value self(String self) {		return new Value().name(Attr.self).text(self);	}	public Value order(int number) {		return new Value().name(Attr.order).text(String.valueOf(number));	}	public Value grow(int number) {		return new Value().name(Attr.grow).text(String.valueOf(number));	}	public Value shrink(int number) {		return new Value().name(Attr.shrink).text(String.valueOf(number));	}	public Value basis(String pixels) {		return new Value().name(Attr.basis).text(pixels);	}	public Value flex(int grow, int shrink, String basis) {		return new Value().name(Attr.flex).text(String.format("%d %d %s", grow, shrink, basis));	}	public Value[] center() {		return new Value[] { this.display(), this.justify(Justify.center), this.content(Items.center) };	}}